!function(){"use strict";function subFamiliaCtrl($scope,_modalSvc,_commonSvc,_nombreModal,mS,toast,form){$scope.dataSearch={pageIndex:1,pageSize:10,maxSize:5},$scope.totalRecords=0,$scope.recordsQuantity=[5,10,25,50,100,200,500],$scope.getSubFamilias=function(){try{showLoader(),mS.getData("get","/SubFamilia/Get?json="+JSON.stringify($scope.dataSearch)).then(response=>{if("0"==response.id)return hideLoader(),void toast.toastr("warning",response.message,response.titleSms);$scope.subFamilias=JSON.parse(response.data)||[],$scope.totalRecords=$scope.subFamilias.length>0?$scope.subFamilias[0].totalRecords:0,hideLoader()})}catch(error){hideLoader(),console.log(error)}},$scope.getSubFamilias(),$scope.pagechanged=function(){$scope.getSubFamilias()},$scope.changePageSize=function(){$scope.dataSearch.pageIndex=1,$scope.getSubFamilias()},$scope.exportTableToExcel=()=>{try{showLoader();const subFamilias=$scope.subFamilias.map(item=>({codigo:item.codigo,descripcion:item.descripcion}));_commonSvc.exportTableToExcel({arr:subFamilias,fileName:"SubFamilias"})}catch(error){hideLoader(),console.log(error)}},$scope.openModalAdd=async function(){const{subFamilia:subFamilia}=_nombreModal,{ModalSubFamiliaCtrl:ModalSubFamiliaCtrl}=await import(`./../../modal/${subFamilia.MODAL_CTRL}`),modalDialogRef=_modalSvc.openModalCustom({controller:ModalSubFamiliaCtrl,template:`SubFamilia/${subFamilia.MODAL_CSHTML}`,size:"md"});modalDialogRef.result.then(result=>{"object"==typeof result&&$scope.getSubFamilias()})},$scope.openModalUpdate=async function(data){const{subFamilia:subFamilia}=_nombreModal,{ModalSubFamiliaCtrl:ModalSubFamiliaCtrl}=await import(`./../../modal/${subFamilia.MODAL_CTRL}`),modalDialogRef=_modalSvc.openModalCustom({controller:ModalSubFamiliaCtrl,template:`SubFamilia/${subFamilia.MODAL_CSHTML}`,size:"md",params:data});modalDialogRef.result.then(result=>{"object"==typeof result&&$scope.getSubFamilias()})},$scope.delete=async function({idSubFamilia:idSubFamilia}){let{isConfirmed:isConfirmed}=await Swal.fire({icon:"warning",html:"<small>Esta seguro/a de eliminar esta subfamilia ahora?</small>",showCinfirmButton:!0,confirmButtonText:"Si, eliminar",showCancelButton:!0,cancelButtonText:"No, cancelar",allowOutsideClick:!1});isConfirmed&&mS.getData("delete","/SubFamilia/Delete?id="+idSubFamilia).then(response=>{"0"!=response.code?"1"==response.code&&(toast.toastr("success",response.message,response.titleSms),$scope.getSubFamilias()):toast.toastr("warning",response.message,response.titleSms)})}}app.controller("subFamiliaCtrl",subFamiliaCtrl),subFamiliaCtrl.$inject=["$scope","modalService","commonService","nombreModal","mainService","toastService","formulario"]}(window.angular);